import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 100005;
    static final int MODULUS = 1000000007;
    static long[] array_dp = new long[17];

    static long recursiveSolve(long value, int depth) {
        if (depth == 0) {
            return (value == 0) ? 0 : MODULUS;
        }
        long divisionCount = value / array_dp[depth];
        if (value % array_dp[depth] == 0) {
            return depth * divisionCount;
        }
        long optionA = recursiveSolve(Math.abs(value - array_dp[depth] * (divisionCount + 1)), depth - 1) + depth;
        long optionB = recursiveSolve(value - array_dp[depth] * divisionCount, depth - 1);
        return Math.min(depth * (divisionCount + 1) + optionA - depth, depth * divisionCount + optionB);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        array_dp[1] = 1;
        for (int i = 2; i < 17; ++i) {
            array_dp[i] = array_dp[i - 1] * 10 + 1;
        }
        long input_value = scanner.nextLong();
        System.out.println(recursiveSolve(input_value, 16));
        scanner.close();
    }
}
